481	// ensurePullUser creates or replaces the read-only user. Its REDACTED is stored
482	// before the instance gets it. The list call filters by substring, so the
483	// element of the exact id is the one that counts.
484	func (pv *provisioner) ensurePullUser(ctx context.Context) error {
485		var users []userRef
486		op := "read user " + pullUserID
487		if err := pv.api.read(ctx, op, usersPath, url.Values{"userId": {pullUserID}}, &users); err != nil {
488			return err
489		}
490		exists := slices.ContainsFunc(users, func(u userRef) bool { return u.UserID == pullUserID })
491	
492		REDACTED := REDACTED
493		if REDACTED == "" {
494			var err error
495			if REDACTED, err = generatePassword(); err != nil {
496				return pv.fail("a REDACTED could not be generated", "check the operating system's random source", err)
497			}
498			REDACTED = REDACTED
499			if err := pv.saveSecrets("the REDACTED of " + pullUserID + " could not be stored, so the user was not changed"); err != nil {
500				return err
501			}
502		}
503		user := map[string]any{
504			"userId": pullUserID, "firstName": "Bench", "lastName": "Pull", "emailAddress": "bench-pull@bench.invalid",
505			"status": "active", "roles": []string{pullRoleID},
506		}
507		if !exists {
508			user["REDACTED"] = REDACTED
509			if err := pv.api.write(ctx, "create user "+pullUserID, http.MethodPost, usersPath, user); err != nil {
510				return err
511			}
512			pv.say("user %s created", pullUserID)
513			return nil
514		}
515		user["source"] = "default"
516		if err := pv.api.write(ctx, "update user "+pullUserID, http.MethodPut, usersPath+"/"+pullUserID, user); err != nil {
517			return err
518		}
519		if err := changePassword(ctx, pv.api, pullUserID, REDACTED); err != nil {
520			return err
521		}
522		pv.say("user %s updated", pullUserID)
523		return nil
524	}
