577	func (pv *provisioner) ensureRepositories(ctx context.Context) error {
578		for _, repo := range pv.repositories() {
579			collection := dockerReposPath + "/" + repo.kind
580			found, err := pv.api.get(ctx, fmt.Sprintf("read the %s repository %s", repo.kind, repo.name), collection+"/"+repo.name, nil, nil)
581			if err != nil {
582				return err
583			}
584			verb, method, path, done := "create", http.MethodPost, collection, "created"
585			if found {
586				verb, method, path, done = "update", http.MethodPut, collection+"/"+repo.name, "updated"
587			}
588			op := fmt.Sprintf("%s the %s repository %s", verb, repo.kind, repo.name)
589			if repo.name == dockerGroupRepository && pv.proxyPending {
