79	// client is the REST client of one Nexus instance. It follows no redirection
80	// (an answer that moves the call elsewhere would carry the credentials with
81	// it), reads at most maxResponseBytes of an answer, and never logs a header.
82	type client struct {
83		base     string
84		user     string
85		REDACTED string
86		http     *http.Client
87	}
88	
89	// newClient returns a client for baseURL, authenticating with Basic auth as user
90	// unless user is empty (the calls that need no account).
91	func newClient(baseURL, user, REDACTED string) *client {
92		transport := http.DefaultTransport.(*http.Transport).Clone()
93		// The bench is reached directly: a proxy named by the environment would
94		// receive the credentials.
95		transport.Proxy = nil
96		return &client{
97			base:     strings.TrimRight(baseURL, "/"),
98			user:     user,
99			REDACTED: REDACTED,
100			http: &http.Client{
101				Timeout:       clientTimeout,
102				Transport:     transport,
103				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
104			},
105		}
106	}
107	
108	// closeIdle drops the connections the client keeps open.
109	func (c *client) closeIdle() { c.http.CloseIdleConnections() }
110	
111	// request is one REST call.
112	type request struct {
113		op          string
114		method      string
115		path        string
116		query       url.Values
117		contentType string
118		body        []byte
119	}
120	
121	// response is what the instance answered.
122	type response struct {
123		status int
124		header http.Header
125		body   []byte
126		// remoteURLBlocked is the verdict of remoteURLRefused on a 400; the body of
127		// an answer outside 2xx is read for it and dropped.
128		remoteURLBlocked bool
129	}
130	
131	// do sends r and returns the answer whatever its status. The error is a
132	// *transportError or a *tooLargeError.
133	func (c *client) do(ctx context.Context, r request) (response, error) {
134		target := c.base + r.path
135		if len(r.query) > 0 {
136			target += "?" + r.query.Encode()
137		}
138		var body io.Reader
139		if r.body != nil {
140			body = bytes.NewReader(r.body)
141		}
142		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
143		if err != nil {
144			return response{}, &transportError{Op: r.op, Err: err}
145		}
146		req.Header.Set("Accept", "application/json")
147		if r.contentType != "" {
148			req.Header.Set("Content-Type", r.contentType)
149		}
150		if c.user != "" {
151			req.SetBasicAuth(c.user, c.REDACTED)
152		}
153		resp, err := c.http.Do(req)
154		if err != nil {
155			return response{}, &transportError{Op: r.op, Err: err}
156		}
157		defer func() { _ = resp.Body.Close() }()
158		if resp.StatusCode < 200 || resp.StatusCode > 299 {
159			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
160			return response{
161				status: resp.StatusCode, header: resp.Header,
162				remoteURLBlocked: resp.StatusCode == http.StatusBadRequest && remoteURLRefused(refused),
163			}, nil
164		}
165		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
166		if err != nil {
167			return response{}, &transportError{Op: r.op, Err: err}
168		}
169		if len(data) > maxResponseBytes {
170			return response{}, &tooLargeError{Op: r.op}
171		}
172		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
173	}
174	
175	// expect sends r and turns a status outside 2xx into an *APIError.
176	func (c *client) expect(ctx context.Context, r request) (response, error) {
177		resp, err := c.do(ctx, r)
178		if err != nil {
179			return resp, err
180		}
181		if resp.status < 200 || resp.status > 299 {
182			return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked}
183		}
184		return resp, nil
185	}
