187	// remoteURLRefused reports whether body is a Nexus validation error list with
188	// an entry on proxy.remoteUrl whose message says the host did not resolve:
189	// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
190	// Only that verdict leaves the function: no text of the answer is kept. The
191	// content type of the answer is vendor specific, so only the JSON is read; a
192	// body past drainBytes was cut and is not trusted.
193	func remoteURLRefused(body []byte) bool {
194		if len(body) > drainBytes {
195			return false
196		}
197		var errs []validationError
198		if err := json.Unmarshal(body, &errs); err != nil {
