1153	// decodeRepo checks the keys of the Repository configuration documented above.
1154	func (f *fakeNexus) decodeRepo(kind string, body []byte) (map[string]any, string) {
1155		m, ok := decodeObject(body)
1156		if !ok {
1157			return nil, "not a JSON object"
1158		}
1159		need := func(path ...string) bool { return jsonAt(m, path...) != nil }
1160		if !nonEmptyString(m, "name") {
1161			return nil, "name is required"
1162		}
1163		if _, isBool := m["online"].(bool); !isBool {
1164			return nil, "online must be a boolean"
1165		}
1166		blob, _ := jsonAt(m, "storage", "blobStoreName").(string)
1167		if !slices.Contains(f.blobStores, blob) {
1168			return nil, "the blob store " + blob + " does not exist"
1169		}
1170		for _, path := range [][]string{
1171			{"storage", "strictContentTypeValidation"}, {"docker", "v1Enabled"}, {"docker", "forceBasicAuth"},
1172		} {
1173			if !need(path...) {
1174				return nil, strings.Join(path, ".") + " is required"
1175			}
1176		}
1177		switch kind {
1178		case "hosted":
1179			if !need("storage", "writePolicy") {
1180				return nil, "storage.writePolicy is required"
1181			}
1182		case "proxy":
1183			if s, _ := jsonAt(m, "proxy", "remoteUrl").(string); s == "" {
1184				return nil, "proxy.remoteUrl is required"
1185			}
1186			for _, path := range [][]string{{"proxy", "contentMaxAge"}, {"proxy", "metadataMaxAge"}, {"dockerProxy", "indexType"}} {
1187				if !need(path...) {
1188					return nil, strings.Join(path, ".") + " is required"
1189				}
1190			}
1191		case "group":
1192			if !need("docker", "httpPort") {
1193				return nil, "docker.httpPort is required"
1194			}
1195			members, isList := jsonAt(m, "group", "memberNames").([]any)
1196			if !isList {
1197				return nil, "group.memberNames must be an array"
1198			}
1199			for _, member := range members {
1200				name, _ := member.(string)
1201				if _, hosted := f.repos["hosted"][name]; !hosted {
1202					if _, proxy := f.repos["proxy"][name]; !proxy {
1203						return nil, "the group member " + name + " does not exist"
1204					}
1205				}
1206			}
1207		}
1208		return m, ""
1209	}
