1221	func nonEmptyString(m map[string]any, key string) bool {
1222		s, ok := m[key].(string)
1223		return ok && s != ""
1224	}
1225	
1226	func deepCopy(m map[string]any) map[string]any {
1227		data, err := json.Marshal(m)
1228		if err != nil {
1229			panic(err)
1230		}
1231		var out map[string]any
1232		if err := json.Unmarshal(data, &out); err != nil {
1233			panic(err)
1234		}
1235		return out
1236	}
