1238	// jsonAt follows keys through nested objects; nil when any step is absent.
1239	func jsonAt(m map[string]any, keys ...string) any {
1240		var cur any = m
1241		for _, k := range keys {
1242			obj, ok := cur.(map[string]any)
1243			if !ok {
1244				return nil
1245			}
1246			cur = obj[k]
1247		}
1248		return cur
1249	}
1250	
1251	// stringsAt reads the array of strings at keys; nil when it is not one.
1252	func stringsAt(m map[string]any, keys ...string) []string {
1253		list, ok := jsonAt(m, keys...).([]any)
1254		if !ok {
1255			return nil
1256		}
1257		out := make([]string, 0, len(list))
1258		for _, v := range list {
1259			s, _ := v.(string)
1260			out = append(out, s)
1261		}
1262		return out
1263	}
