79	// client is the REST client of one Nexus instance. It follows no redirection
80	// (an answer that moves the call elsewhere would carry the credentials with
81	// it), reads at most maxResponseBytes of an answer, and never logs a header.
82	type client struct {
83		base     string
84		user     string
85		REDACTED string
86		http     *http.Client
87	}
88	
89	// newClient returns a client for baseURL, authenticating with Basic auth as user
90	// unless user is empty (the calls that need no account).
91	func newClient(baseURL, user, REDACTED string) *client {
92		transport := http.DefaultTransport.(*http.Transport).Clone()
93		// The bench is reached directly: a proxy named by the environment would
94		// receive the credentials.
95		transport.Proxy = nil
96		return &client{
97			base:     strings.TrimRight(baseURL, "/"),
98			user:     user,
99			REDACTED: REDACTED,
100			http: &http.Client{
101				Timeout:       clientTimeout,
102				Transport:     transport,
103				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
104			},
105		}
106	}
